pub unsafe extern "C" fn foo(in_ptr: *const i8, c: i8) -> i32 {
    if !in_ptr.is_null() {
        if let Ok(in_str) = CStr::from_ptr(in_ptr).to_str() {
            let c_as_char = (c as u8) as char;
            return crate::logic::foo(in_str, c_as_char);
        }
    }
    0
}

