pub unsafe extern "C" fn driver(in_ptr: *const i8) {
    if !in_ptr.is_null() {
        if let Ok(in_str) = CStr::from_ptr(in_ptr).to_str() {
            crate::logic::driver_impl(in_str);
        }
    }
}
